function demoMain(idx,label){
  var files={"main.js":"function start(){init();run();}","util.js":"function init(){cfg=load();}","app.js":"function run(){while(1){tick();}}","cfg.js":"function load(){return read();}"};
  var pats=["function","init","run","load"]; var pat=pats[idx%pats.length]; var hits=[];
  for(var f in files){var lines=files[f].split(";");for(var i=0;i<lines.length;i++){if(lines[i].indexOf(pat)>=0)hits.push(f+":"+lines[i].trim());}}
  return "["+label+"] pattern '"+pat+"' matched "+hits.length+" lines: "+hits.join(" | ");
}

